const e=Object.freeze({title:"Terms of Use",updated:"Local draft · 14 October 2026",intro:"These terms describe the behavior of this local Cimoa build. They are not published production terms and do not identify a configured operator, legal entity or support contact.",sections:[["1. Local build and eligibility","Cimoa is designed for university students aged 18 or older. This build stores accounts locally and does not independently confirm that an email address or student status is genuine."],["2. Your local account","Keep the password for your on-device account private. Registration, login and password reset operate only against account data stored on this device. Apple sign-in is not configured."],["3. Community conduct","Be respectful. Do not harass, threaten, impersonate, pressure or exploit another person, and do not share illegal or unsafe content. Local reports are personal records and are not delivered to a moderation team."],["4. Local data and unavailable services","Profiles, messages, event activity, settings and safety records are stored on this device. Remote messaging, matching, email verification, support delivery and moderation services are not configured unless a screen explicitly reports a real available capability."],["5. Coins and purchases","Coins are local ledger entries with no cash value. StoreKit products, payment processing and receipt verification are not configured, so a purchase attempt cannot add coins and must report failure, cancellation or timeout."],["6. Events and personal safety","Event details come from local project data. Cimoa does not provide a live organiser, emergency or attendance service in this build. Use appropriate campus or emergency channels when real-world help is needed."],["7. Blocking and account deletion","Blocking removes the current private connection, request, match and chat data; unblocking does not restore them. Deleting an account removes its private local records and cannot be undone through this build."],["8. Publication status","A production operator, jurisdiction, dispute process, legal contact and release terms have not been supplied. This local draft is for development and testing and must not be treated as approval for public release."]]}),t=Object.freeze({title:"Privacy Policy",updated:"Local draft · 14 October 2026",intro:"This notice describes information handled by this local Cimoa build. It is not a published production privacy policy and does not identify a configured controller, processor or privacy contact.",sections:[["1. Information stored locally","The app may store your email, salted password credential, date of birth, profile fields, preferences, local verification state, messages, event activity, safety records, coin ledger and support drafts on this device."],["2. Photos, audio and other media","Media you choose is stored in the browser or app’s local media database. This build does not upload that media to a Cimoa server. A missing or denied device capability is reported as unavailable."],["3. Profile visibility","Your visibility settings control which local profile fields appear in Discover, Auto Match and event surfaces. Your email and date of birth are not shown on public profile cards. Existing chats may remain visible when discovery is hidden."],["4. Messages and connections","Private chats are available only for a mutual local connection. Blocking removes the current private relationship, request, match, conversation and its messages. Unblocking does not recreate deleted records."],["5. Reports and support drafts","Reports and support notes are saved only on this device. They are not sent to a moderation or support service, and no review status, decision or ticket is created."],["6. Authentication and permissions","Email registration and password reset are local. The fixed code does not prove control of an email address or student status. Apple sign-in is not configured. System permission status comes from the browser or iOS host and cannot be changed by Cimoa itself."],["7. Purchases and external services","StoreKit products, payment receipt verification, remote matching, push delivery and production service providers are not configured. The app does not claim data sharing with providers that have not been supplied."],["8. Retention, clearing and deletion","Local records remain until changed, deleted through the app or removed with site/app data. Account deletion removes that account’s private local entities and media where the local media database permits. Clearing app data can remove all local accounts."],["9. Production gaps","A production operator, legal basis, jurisdiction, retention schedule, data-rights process and privacy contact have not been provided. Those items must be completed before public release."]]});export{t as p,e as t};
